// NFR13: one trace id per request, generated by the proxy and returned in X-Trace-Id and in every
// error body, so a member's report can be matched to the log line. A trace id sent by the client
// is never used: the proxy overwrites the request header.
import { randomBytes } from "node:crypto";

export const TRACE_HEADER = "x-trace-id";
const TRACE_ID = /^[0-9a-f]{32}$/;

export function newTraceId(): string {
  return randomBytes(16).toString("hex");
}

/** The proxy's trace id for this request, or a new one if the request did not pass the proxy. */
export function traceIdOf(headers: Headers): string {
  const value = headers.get(TRACE_HEADER);
  return value !== null && TRACE_ID.test(value) ? value : newTraceId();
}
